{
    str                     result = '';
    TFMCondition            condition;
    TFMConditionOperator    logicalOperator;
    MapEnumerator           mEnum = conditions.getEnumerator();

    MethodName              mName;
    TFMConnectedConditions  conditionsForMethod;        

    if (!conditions.exists(_methodName))
    {
        return '';
    }
    conditionsForMethod = this.conditionsForMethod(_methodName);

    /*mEnum = conditionsForMethod.getEnumerator();
    while (mEnum.moveNext())
    {
        condition = mEnum.currentValue();
        result += condition.parmExpression();

    }*/


    return result;
}
